def write_echo(path,text):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    env=dict(os.environ);env["AQ_OUT"]=str(path);env["AQ_TXT"]=text
    r=subprocess.run(["bash","-c",'echo -E "$AQ_TXT" > "$AQ_OUT"'],env=env)
    if r.returncode!=0:
        error(f"echo write failed for {path} (exit {r.returncode})")
    elif not path.name.startswith("."):
        log(f"wrote {path}")
    return r.returncode
def fval(s):
    if s.lower()=="true":return True
    if s.lower()=="false":return False
    try:return int(s)
    except Exception:pass
    try:return float(s)
    except Exception:return s
def lenient_json(text):
    out=[];i=0;n=len(text);in_str=False;esc=False
    while i<n:
        c=text[i]
        if in_str:
            out.append(c)
            if esc:esc=False
            elif c=="\\":esc=True
            elif c=='"':in_str=False
            i+=1;continue
        if c=='"':
            in_str=True;out.append(c);i+=1;continue
        if c=="/" and i+1<n and text[i+1]=="/":
            while i<n and text[i] not in "\r\n":i+=1
            continue
        if c=="/" and i+1<n and text[i+1]=="*":
            i+=2
            while i+1<n and not (text[i]=="*" and text[i+1]=="/"):i+=1
            i+=2;continue
        out.append(c);i+=1
    return json.loads(re.sub(r",(\s*[}\]])",r"\1","".join(out)))
def _states(text):
    n=len(text);i=0;st=0
    while i<n:
        c=text[i]
        if st==0:
            if c=='"':
                j=i+1
                while j<n:
                    if text[j]=="\\":j+=2;continue
                    if text[j]=='"':break
                    j+=1
                yield(i,min(j+1,n),1);i=min(j+1,n);continue
            if c=="/" and i+1<n and text[i+1]=="/":
                j=text.find("\n",i)
                if j<0:j=n
                yield(i,j,3);i=j;continue
            if c=="/" and i+1<n and text[i+1]=="*":
                j=text.find("*/",i+2)
                e=j+2 if j>=0 else n
                yield(i,e,4);i=e;continue
            yield(i,i+1,0);i+=1
        else:i+=1
def _match_brace(text,open_i):
    depth=0
    for a,b,st in _states(text):
        if st or a<open_i:continue
        for ch in text[a:b]:
            if ch=="{":depth+=1
            elif ch=="}":
                depth-=1
                if depth==0:return b-1
    return -1
def _line_indent(text,pos):
    ls=text.rfind("\n",0,pos)+1;k=ls
    while k<len(text) and text[k] in " \t":k+=1
    return text[ls:k]
def _find_key(text,key):
    pat='"'+key+'"'
    for a,b,st in _states(text):
        if st==1 and text[a:b]==pat:return a
    return -1
def _ff_block(flags,key_ind):
    if not flags:return "{}"
    inner=key_ind+"    "
    body=""
    for k,v in flags.items():
        body+=inner+json.dumps(k)+": "+json.dumps(v)+",\n"
    return "{\n"+body[:-2]+"\n"+key_ind+"}"
def merge_fflags_text(text,flags):
    j=_find_key(text,"fflags")
    if j>=0:
        colon=text.find(":",j)
        ob=text.find("{",colon)
        cb=_match_brace(text,ob)
        ind=_line_indent(text,j)
        return text[:ob]+_ff_block(flags,ind)+text[cb+1:]
    depth=0;close=-1
    for a,b,st in _states(text):
        if st:continue
        for ch in text[a:b]:
            if ch=="{":depth+=1
            elif ch=="}":
                depth-=1
                if depth==0:close=a
    if close<0:raise ValueError("root object not found")
    k=close-1
    while k>=0 and text[k] in " \t\r\n":k-=1
    comma="" if text[k] in "{," else ","
    prop='    "fflags": '+_ff_block(flags,"    ")+comma+"\n"
    return text[:close]+prop+text[close:]
